// Discount helpers
export function percentOff(total, pct) {
  return Math.round(total * (100 - pct)) / 100;
}

// Discount codes. WINTER is valid while now < 2025-01-01T00:00:00Z.
const WINTER_CUTOFF_MS = Date.UTC(2025, 0, 1);

// Applies a discount code to `total`. `now` is a Date supplied by the caller;
// the system clock is never read here.
// Returns { ok, total, reason }. reason is null on success, otherwise one of
// 'INVALID_INPUT', 'INVALID_CODE', 'EXPIRED'.
export function applyCode(total, code, now) {
  if (typeof total !== 'number' || !Number.isFinite(total) || total < 0) {
    return { ok: false, total, reason: 'INVALID_INPUT' };
  }
  if (!(now instanceof Date) || isNaN(now.getTime())) {
    return { ok: false, total, reason: 'INVALID_INPUT' };
  }

  const normalized = typeof code === 'string' ? code.trim().toUpperCase() : '';

  switch (normalized) {
    case 'SAVE10':
      return { ok: true, total: percentOff(total, 10), reason: null };
    case 'FIVE':
      return {
        ok: true,
        total: Math.max(0, Math.round((total - 5) * 100) / 100),
        reason: null,
      };
    case 'WINTER':
      if (now.getTime() < WINTER_CUTOFF_MS) {
        return { ok: true, total: percentOff(total, 20), reason: null };
      }
      return { ok: false, total, reason: 'EXPIRED' };
    default:
      return { ok: false, total, reason: 'INVALID_CODE' };
  }
}

